<?php $items=all('transportadores');$edit=isset($_GET['edit'])?one('transportadores',(int)$_GET['edit']):null; ?>
<div class="two-col"><section class="panel"><div class="panel-header"><div><h2><?=$edit?'Editar transportador':'Cadastrar transportador'?></h2><p>Empresas ou profissionais responsáveis pela carga</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save_carrier"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>">
<label>Nome / razão social<input class="form-control" required name="nome" maxlength="150" placeholder="Transportadora ABC" value="<?=h($edit['nome']??'')?>"></label>
<label>CPF ou CNPJ (opcional)<input class="form-control" name="documento" maxlength="25" placeholder="Documento" value="<?=h($edit['documento']??'')?>"></label>
<label>Telefone (opcional)<input class="form-control" name="telefone" maxlength="25" placeholder="(45) 99999-9999" value="<?=h($edit['telefone']??'')?>"></label>
<label>Tipo de veículo (opcional)<input class="form-control" name="veiculo" maxlength="120" placeholder="Caminhão baú" value="<?=h($edit['veiculo']??'')?>"></label>
<div class="form-actions"><button class="btn btn-purple" type="submit">✓ &nbsp;Salvar transportador</button><?php if($edit):?><a class="btn btn-outline-secondary" href="index.php?page=transportadores">Cancelar</a><?php endif;?></div></form></section>
<section class="panel"><div class="panel-header"><div><h2>Transportadores cadastrados</h2><p><?=count($items)?> responsáveis disponíveis</p></div></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Transportador</th><th>Telefone</th><th>Veículo</th><th></th></tr></thead><tbody>
<?php foreach($items as $x):?><tr><td><b><?=h($x['nome'])?></b><small><?=h($x['documento'])?></small></td><td><?=h($x['telefone']?:'—')?></td><td><?=h($x['veiculo']?:'—')?></td><td class="action-cell"><a class="text-link" href="index.php?page=transportadores&amp;edit=<?=$x['id']?>">Editar</a><form method="post" onsubmit="return confirm('Excluir este transportador?');"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="transportadores"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-danger" type="submit">Excluir</button></form></td></tr><?php endforeach;?>
<?php if(!$items):?><tr><td colspan="4" class="empty-state">Nenhum transportador cadastrado.</td></tr><?php endif;?></tbody></table></div></section></div>
